import { createContext, useCallback, useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import LeftMenu from '../HomePage/LeftMenu/LeftMenu';
import RightMenu from '../HomePage/RightMenu/RightMenu';
import Posts from '../HomePage/TheFeed/Posts';
import UpMenu from '../HomePage/UpMenu/UpMenu';
import Profile from './Profile';
export const ThemeContext = createContext(null);


function ProfilePage({ activeUser,setActiveUser }) {
    const { email, correnttheme } = useParams();
    const [theme, setTheme] = useState(correnttheme);
    const [postsList, setPostsList] = useState([]);
    const [userPage, setUserPage] = useState(undefined);
    const sameUser = userPage?.displayName === activeUser?.displayName;
    const friends = activeUser?.friends?.includes(userPage?.email);

    const changeTheme = () => {
        setTheme((curr) => { return curr === "light" ? "dark" : "light"; });
    };

    const getUser = useCallback(async () => {
        const response = await fetch('http://localhost:8080/api/users/' + email, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${activeUser.token}`
            },
        });
        const data = await response.json();
        await setUserPage(data);
    }, [activeUser?.token, email])

    useEffect(() => {
        getUserPosts();
        getUser()
    }, [getUser]);

    const getUserPosts = async () => {
        const response = await fetch('http://localhost:8080/api/users/'+ email+ '/posts', {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${activeUser.token}`
        },

        });
        const data = await response.json();
        const sortData = [...data].sort((a, b) => new Date(b.date) - new Date(a.date));
        setPostsList(sortData);
    }

    return (
        <ThemeContext.Provider value={{ theme, changeTheme }}>
            <div className="container- fluid" id={theme}>
                <div className="row upfeed">
                    <UpMenu activeUser={activeUser} changeTheme={changeTheme}  setActiveUser={setActiveUser} postsList={postsList} setPostsList={setPostsList}/>
                </div>
                <div className="row feed">
                    <div className="col-3">
                        <LeftMenu activeUser={activeUser}
                            correnttheme={theme} />
                    </div>
                    <div className="row col-6">

                        {userPage === undefined ? 'Loading...' : <>
                            <Profile userPage={userPage}
                                sameUser={sameUser} 
                                activeUser={activeUser} />
                               
                            {friends && postsList.map((post) =>
                                <Posts {...post}
                                    activeUser={activeUser}
                                    theme={theme}
                                    postsList={postsList}
                                    setPostsList={setPostsList}
                                    key={post._id} />
                            )}
                        </>}
                    </div>
                    <div className="col-3">
                        <RightMenu />
                    </div>
                </div>
            </div>
        </ThemeContext.Provider>

    );
}

export default ProfilePage;
